        with (out/'original.stdout').open('xb') as first,(out/'original.stderr').open('xb') as second:run=subprocess.run(command,cwd=ROOT,stdin=subprocess.DEVNULL,stdout=first,stderr=second,timeout=3600)
        save(out/'process.json',dict(command=command,exit_code=run.returncode));assert run.returncode==0,'Read original.stderr';report=json.loads((out/'analysis/COMPLETED.json').read_bytes());assert report['status']=='PASS_COMPLETE_ORIGINAL_HIFIASM_AND_NATIVE_GRAPH_WORKFLOW' and report['analysis_admitted'] and len(report['analyses'])==1;inspection=json.loads((out/'analysis/inputs'/(spec['paternal']+'.inspection.json')).read_bytes())['stored_count_summary'];assert inspection['entries']==expected['entries'] and inspection['maximumBucketEntries']==expected['maximum_bucket_entries'] and inspection['countHistogram']==expected['histogram'] and inspection['unsignedHashSum']==expected['hash_sum'] and inspection['unsignedHashXor']==expected['hash_xor'];home=out/'analysis/analyses/large-parent-gzip-trio-ul';baseline=ROOT/'build/literature-review/hifiasm-runtime/paper-modes-1/0.19.5-r587/original/0.19.5-r587-trio-ul/assembly';reference={q.name:pin(q) for q in baseline.glob('*.gfa')};actual={q.name:pin(q) for q in (home/'original').glob('*.gfa')};assert reference==actual and reference,'Declared weak-marker additions or gzip input changed the complete original graph output';process=json.loads((home/'process/process.json').read_bytes());assert process['exit_code']==0 and not process['owned_live_after_cleanup'];command=['wsl','-d','JLinAlg-Omics-SAIGE-20261026','--exec','/usr/bin/java','-Xmx128m','-cp',linux(jar),'org.jlinalg.cli.HifiasmVerifyCli','--out',linux(out/'analysis')];verification=subprocess.run(command,capture_output=True,timeout=300);(out/'verify.stdout').write_bytes(verification.stdout);(out/'verify.stderr').write_bytes(verification.stderr);assert verification.returncode==0,verification.stderr.decode();assert pin(parent)=={k:prepared['augmented_parent'][k] for k in ['bytes','sha256']} and all(pin(ROOT/n)==v for n,v in built['source_pins'].items());state.update(status='passed-full-large-parent-gzip-trio-ul-workflow-under128MiB-Java-heap',artifact=built['artifact'],parent_entries=expected['entries'],largest_parent_bucket=expected['maximum_bucket_entries'],java_heap='128MiB',complete_source_graph_views=len(reference),original_graphs_byte_identical=True,all_original_markers_retained=True,synthetic_added_count=1,whole_human_or_plant_assembly_benchmarked=False,source_pins={Path(__file__).resolve().relative_to(ROOT).as_posix():pin(Path(__file__).resolve())})
